from s114_course_common import teach
S='va-sph'
teach(S,'l1',[
(0,'兩盞燈靠多近，你還認得出是兩盞？','視力量分辨細節的能力，不是近視幾百度。', [('MAR','兩點剛能分開的最小夾角，越小越厲害'),('分角′','1度再切60份，其中一份；不是時間的一分鐘'),('視力1.0','參考細節角1′；小數視力＝1/MAR')],'先認角度，再看下面的換算。'),
(2,'一個E字：整體和缺口的大小不同','要讀出方向，得認出缺口，不只看見一團黑。',[('視標','拿給受測者辨認的字母、E或C環'),('整字5′','高度分成五個等寬單位'),('細節1′','筆畫或缺口佔一格，才對應MAR')],'這裡都以1.0標準視標說明；站得更遠，實體字要印更大。'),
(4,'字變大，和走近看，是兩種幫忙','同一個字走近看會顯大；比較視力要記檢查距離。',[('實體高度','紙上的字有幾mm，不因人移動而改變'),('張角','字在你眼前佔多大角度，走近就變大'),('0.5視標','同距離要比1.0的字大2倍')],'先固定字和標準距離，才套距離比；不要把重新放大過的電子表混進來。')])
teach(S,'l2',[
(0,'20/40：分子是你站的位置','它不是度數，也不是看見40%的東西。',[('20英呎','這次站在20英呎檢查'),('40英呎','參考者能從40英呎認出同一大小的字'),('換小數','20÷40＝0.5；兩個長度必須同單位')],'0.5是分辨角的比值，不表示日常視覺功能只剩一半。'),
(2,'四種視力寫法，先統一在比什麼','小數看數字越大越好；MAR和logMAR通常相反。',[('MAR','需要多大的細節角'),('logMAR','把MAR取以10為底的對數，是另一種刻度'),('log怎麼想','MAR每變10倍，logMAR增加1；1→0、10→1')],'不熟對數可先用對照表；不要把小數0.5直接當logMAR 0.5。'),
(4,'M是字的大小；cpd是條紋有多細','M必須連檢查距離一起讀，不能單看字體大小猜視力。',[('1 M字','在1m時整字張5′；在0.4m讀它，小數視力0.4'),('小數視力','距離m÷字體M；下面0.4/M限40cm'),('1週期／cpd','一黑加一白是一組；1度內能放幾組')],'20/20細節1′，黑白一組共2′，所以60′÷2′＝30 cpd。')])
teach(S,'l3',[
(0,'讀對一個小字，分數往下0.02','先確認是每行5字、行差0.10的logMAR表。',[('基底0.90','已整行讀對的logMAR分數，不是小數視力'),('再對2字','0.90−2×0.02＝0.86 logMAR'),('為何減分','能讀更小細節代表更好，logMAR往較小方向走')],'若表的行距或字數不同，不能不問條件就每字扣0.02。'),
(2,'視力記錄：分數後面還有測試條件','同樣0.8，裸視、戴鏡或針孔測出的意思不同。',[('sc／cc','不戴矯正鏡／戴矯正鏡'),('PH','透過針孔板量到的視力'),('DVA／NVA／TD','遠視力／近視力／測試距離')],'0.8⁻²表示該行漏2字；依所用表與計分規則記，別和逐字logMAR計分混用。')])
teach(S,'l4',[
(0,'小洞前後比一次，看模糊能否減少','針孔的進步或沒進步都是線索，不能單獨確診。',[('屈光因素','光沒有在網膜對準焦，鏡片可能有改善空間'),('PH改善','限制進光後更清楚，支持有可矯正因素'),('PH未改善','也可能孔沒對準、太暗或其他原因；必要時進一步評估')],'課堂20/30是使用情境參考，不是所有人一定要照同一門檻。'),
(2,'模糊圈：一個亮點被攤開的光斑','不是網膜裡有個圓形器官，是光沒有對焦時的影像。',[('限制進光','像相機縮光圈，失焦光斑可變小'),('景深','前後一段距離看起來還能接受清楚'),('繞射','光通過很小孔會散開；孔過小反而失去細節')],'1～1.5mm是常見折衷；變暗和繞射一起限制效果。'),
(4,'PH 0.6：只報這次透過孔看到多少','它不是完整排除屈光問題，也不等於最終最佳矯正視力。',[('先記條件','裸視或戴鏡、距離、孔徑與結果'),('結果0.6','這次針孔條件下讀到0.6'),('還要做什麼','按情境驗光或眼部檢查，才能解釋原因')],'原課例題讀成測試紀錄，不用PH數字直接推疾病或神經功能上限。')])
teach(S,'l5',[
(0,'網膜是接光的屏幕；近視是太早聚焦','以下都先假設眼睛放鬆、看遠方。',[('正視','遠光剛好集中在網膜'),('近視','在網膜前先集中，到網膜時又散開'),('負鏡片','先讓光發散一些，使整體焦點往後移')],'D是鏡片力量；視力好壞不是只由D決定。'),
(2,'遠視：眼睛可能一直偷偷加力','遠視不一定看遠不清楚，因為調節可能補回焦點。',[('遠視','放鬆看遠時力量不足，預計焦點在網膜後'),('調節','睫狀肌讓水晶體增加收光力量'),('正鏡片','幫忙收光，減少眼睛自己補的負擔')],'遠視虛遠點在眼後的物方位置，不能把它當網膜後的那個成像焦點。'),
(4,'遠點：眼睛不加力時，能對準焦的目標位置','近視度數越深，這個位置越靠近眼睛。',[('FP／far point','遠點；不是眼內焦點'),('眼前20cm','先換0.20m，近似矯正度數−1/0.20＝−5D'),('視力與D','同一D可有不同視力，講義對照只可當粗估')],'簡化倒數關係有參考平面與調節放鬆前提，不能用視力表唯一反推處方。')])
teach(S,'l6',[
(0,'相機屏幕放錯位置，和鏡頭力量不對','軸性看眼軸長短；屈光性看收光力量。',[('軸性近視','力量近似固定，眼軸偏長'),('屈光性近視','長度近似固定，角膜／水晶體力量偏強'),('遠視','相反的偏短或力量不足')],'兩種因素可同時存在，不是每個近視都能只分到一邊。'),
(2,'簡化眼：用一個鏡面代表整個系統','22.22mm是這個模型的主平面到網膜距離，不是直接否定真人眼軸約24mm。',[('F＝60D','模型的總力量'),('n＝1.333','眼內介質的折射率'),('L＝n/F','結果以m算，最後乘1000變mm')],'模型附近眼軸每長1mm，近視量約增加2.7D；不要外推成所有眼睛固定換算。'),
(4,'正視化：眼球長大時，長度和力量一起調整','兒童不是把所有部位等比例放大。',[('正視化','眼軸、角膜和水晶體等配合，屈光趨近正視'),('早發近視','較早開始，後續進展與高度近視風險通常較高'),('年齡數字','講義的族群概況，不是個人的保證時程')],'角膜K、眼軸與屈光處方是不同測量，不能只看其中一項就判所有變化。')])
teach(S,'l7',[
(0,'把遠視分成「藏起來」和「補不掉」兩層','先拆全遠視，再拆顯性遠視，不是五個數字全部相加。',[('全＝顯性＋隱性','平常查到的，加上調節藏住的'),('顯性＝絕對＋機能','怎麼加力都補不掉的，加上還能靠調節補的'),('睫狀肌麻痺','暫時減少調節，幫忙看出隱性；不只是瞳孔變大')],'年齡上升調節變少，機能部分可轉成絕對；隱性減少時顯性才相對增加。'),
(2,'同一人的試鏡過程，分三次讀','先找到最好視力，再比能接受的正鏡範圍。',[('最低正鏡達最佳','課堂用作絕對遠視量'),('最高正鏡仍最佳','課堂用作顯性遠視量'),('麻痺後多出的量','隱性；顯性減絕對則是機能')],'例：最低+1.50、最高+4.00、另多+1.50 →機能2.50、全5.50D；每一步都指同一個人。')])
